&=1 + z + 3 z^{2} + 3 z^{3} + 6 z^{4} + 8 z^{5} + 12 z^{6} + 16 z^{7} + 23 z^{8}
+ 29 z^{9} + 39 z^{10} +\cdots.
\end{align*}
For instance, the six effective divisors of degree~$4$ in~$\mathbb{E}_{[0]}$ predicted by
the generating function are
\[
  (0,0,4,0),(0,0,2,2),(0,0,0,4),(1,1,2,0),(1,1,0,2),(2,2,0,0),
\]
which we get from~$\mathcal{S}_{[0]}$ by adding appropriate multiples of elements
of~$\mathcal{P}=\{8v_1,8v_2,2v_3,q\}$.

As another example, let $D=v_1-q=(1,0,0,-1)$.  To find~$\mathcal{S}_{[D]}$, 
add~$D$ to each of the divisors in~$\mathcal{S}_{[0]}$, then take their standard
representatives as elements of~$\mathbb{Z}_8\times\mathbb{Z}_8\times\mathbb{Z}_2\times\mathbb{Z}_1$:
\begin{align*}
  \mathcal{S}_{[D]}= \{ &(1,0,0,0),(2,1,0,0),(3,2,0,0),(4,3,0,0),
    (5,4,0,0),(6,5,0,0),(7,6,0,0),(0,7,0,0)\\[8pt]
&(1,4,1,0),(2,5,1,0),(3,6,1,0),(4,7,1,0),
(5,0,1,0),(6,1,1,0),(7,2,1,0),(0,3,1,0)\}.
\end{align*}
Therefore,
\begin{align*}
\Lambda_{[D]}(z)&=\frac{z+z^3+z^4+z^5+2z^6+2z^7+2z^8+z^9+2z^{10}+z^{11}+z^{12}+z^{13}}{(1-z)(1-z^2)(1-z^8)^2}\\[5pt]
&=\frac{x(1-x+x^3)}{(1+x)^2(1+x^4)(1-x)^4}\\[8pt]
&= z + z^{2} + 3 z^{3} + 4 z^{4} + 7 z^{5} + 10 z^{6} + 15 z^{7} + 20 z^{8} + 28
z^{9} + 35 z^{10}+\cdots.
\end{align*}

\subsubsection{Cycle graphs.}\label{example: ps-cycle} Let~$C_n$ be the cycle graph on~$n$ vertices, with
vertices~$v_1,\dots,v_n$ around the cycle.  Take~$q=v_n$. It is well-known
that~$\Jac(C_n)\simeq\mathbb{Z}/n\mathbb{Z}$, with generator~$D_1:=[v_1-q]$ and such
that $D_j:=[v_{j}-q]=j[v_1-q]$ for all~$j$, where the indices are determined
modulo~$n$.  Therefore,~$\ord_{q}(v_i)=n/\gcd(i,n)$ for all~$i$.  For
convenience, take~$\ell_{v_i}=n$ for~$i=1,\dots,n-1$ and~$\ell_q=1$.  The reduced
Laplacian~$\tilde{L}$ is the~$(n-1)\times(n-1)$ tridiagonal matrix with~$2$s on the
diagonal and~$-1$s on the super and subdiagonals.  It is straightforward to
reduce~$\tilde{L}$ to its Hermite form, which is~$I_{n-1}+B_{n-1}$ where~$I_{n-1}$ is the
identity matrix and~$B_{n-1}$ is a matrix whose rows are all~$0$-vectors except for
the last row, which is the vector~$(1,2,\dots,n-1)$.  See Figure~\ref{fig:
ps-cycle} for an example.
