\noindent As an instance of Theorem~\ref{thm: permutation invariants}, apply the
Reynold's operator with~$\omega=\mathbf{i}\mkern1mu=\sqrt{-1}$ to the two~$6$-divisible necklaces
to find a basis for~$\C[\mathbf{y}]_{[D_1],2}^{\Gamma'}$:
\begin{align*}
  4f_{[2000]} &= \mathbf{i}\mkern1mu^{-1}y_2^2+\mathbf{i}\mkern1mu^{-2} y_3^{2}+\mathbf{i}\mkern1mu^{-3}y_4^2+\mathbf{i}\mkern1mu^{-4}y_1^2=
  -\mathbf{i}\mkern1mu y_2^2-y_3^2+\mathbf{i}\mkern1mu y_4^2+ y_1^2\\[5pt]
  4f_{[1100]}&=\mathbf{i}\mkern1mu^{-1}y_2y_3+\mathbf{i}\mkern1mu^{-2}y_3y_4+\mathbf{i}\mkern1mu^{-3}y_4y_1+\mathbf{i}\mkern1mu^{-4}y_1y_2
  =-\mathbf{i}\mkern1mu y_2y_3-y_3y_4+\mathbf{i}\mkern1mu y_1y_4+y_1y_2.
\end{align*}
To change to the basis corresponding to the diagonal representation, substitute
\begin{align*}
  y_1 &= x_1+x_2+x_3+x_4\\
  y_2 &= \mathbf{i}\mkern1mu x_1- x_2-\mathbf{i}\mkern1mu x_3 +x_4\\
  y_3 &= -x_1+ x_2-x_3+x_4\\
  y_4 &= -\mathbf{i}\mkern1mu x_1- x_2+\mathbf{i}\mkern1mu x_3+x_4,
\end{align*}
to find
\begin{align*}
  f_{[2000]}&= 2(x_{1} x_{4} + x_{2} x_{3})\\
  f_{[1100]}&= \left(1+\mathbf{i}\mkern1mu\right)(x_{1} x_{4} -  x_{2} x_{3}),
\end{align*}
which is a basis for~$\C[\mathbf{x}]_{[D_1],2}^{\Gamma}$.  Note that~$x_1x_4$
and~$x_2x_3$ form a monomial basis for~$\C[\mathbf{x}]_{[D_1],2}^{\Gamma}$ whose
exponent vectors are exactly the elements
of~$|D_1+2q|=\left\{(1,0,0,1),(0,1,1,0) \right\}$ in accordance with
Theorem~\ref{thm: invariants}. 

Next, consider the case~$(n,k,j)=(4,2,2)$.  We have~$m_2=3$ and~$n_2=2$.  All
three necklaces in~$\mathcal{N}(4,2)$ are~$3$-divisible.  The corresponding basis
for~$\C[\mathbf{y}]_{[D_2],2}^{\Gamma'}$ is
\begin{align*}
  4f_{[2000]} &= \mathbf{i}\mkern1mu^{-2}y_2^2+\mathbf{i}\mkern1mu^{-4} y_3^{2}+\mathbf{i}\mkern1mu^{-6}y_4^2+y_1^2=
  -y_2^2+y_3^2- y_4^2+ y_1^2\\[5pt]
  4f_{[1100]}&=\mathbf{i}\mkern1mu^{-2}y_2y_3+\mathbf{i}\mkern1mu^{-4}y_3y_4+\mathbf{i}\mkern1mu^{-6}y_4y_1+y_1y_2
  =- y_2y_3+y_3y_4- y_1y_4+y_1y_2\\[5pt]
  4f_{[1010]}&=\mathbf{i}\mkern1mu^{-2}y_2y_4+\mathbf{i}\mkern1mu^{-4}y_3y_1+\mathbf{i}\mkern1mu^{-6}y_4y_2+y_1y_3
  =2y_1y_3- 2y_2y_4.
\end{align*}
Substitute to get a basis for~$\C[\mathbf{x}]_{[D_2],2}^{\Gamma}$:
\begin{align*}
  f_{[2000]}&=x_{1}^{2}+ 2 \, x_{2} x_{4}+  x_{3}^{2}  \\
  f_{[1100]}&= \mathbf{i}\mkern1mu (x_{1}^{2} -  x_{3}^{2})\\
  f_{[1010]}&= -x_{1}^{2} + 2 \, x_{2} x_{4}- x_{3}^{2}.
\end{align*}
The corresponding complete linear system
is~$|D_2+2q|=\left\{(2,0,0,0),(0,1,0,1),(0,0,2,0) \right\}$, which by
Theorem~\ref{thm: invariants} yields the monomial
basis~$\left\{x_1^2,x_2x_4,x_3^2\right\}$ for~$\C[\mathbf{x}]^{\Gamma}_{[D_2],2}$ .
\end{example}

\begin{proof} Let~$\eta=(1,2,\dots,n)$ as in Lemma~\ref{lemma: divisors on C_n}.
  To show injectivity, suppose~$\psi(E)=\psi(E')$ for some pair of
  effective divisors~$E,E'\in\Div^k(C_n)$.  It follows that~$E'=\sigma^i(E)$ for
  some~$i$.  By Lemma~\ref{lemma: divisors on C_n}, working modulo~$n$,
  \[
    j = E'\cdot\eta =\sigma^i(E)\cdot\eta=E\cdot(\eta+i\vec{1})=j+ik\bmod n.
  \]
  If~$\gcd(n,k)=1$, it follows that~$i=0\bmod n$, and hence~$E=E'$.

  For surjectivity, let~$N\in\mathcal{N}(n,k)$ with~$\code(N)=[a_1\dots a_n]$.
  Let~$E:=(a_1,\dots,a_n)\in\Div^k(C_n)$, and say~$E\cdot\eta=m\bmod n$.
  Then $\sigma^i(E)\cdot\eta=m+ik\bmod n$ for each~$i$.  If~$\gcd(n,k)=1$,
  we can take~$i$ so that~$m+ik=j\bmod n$ and define~$E':=\sigma^i(E)$.
  Then~$E'\in|D_j+kq|$ and~$\psi(E')=N$.
\end{proof}

\begin{remark}  If~$N\in\mathcal{N}(n,k)$ and~$\code(N)$ has period~$\ell$, then as we
  saw in the proof of Theorem~\ref{thm: permutation invariants}, both~$\ell|n$
  and~$\ell|k$.  Thus, if~$\gcd(n,k)=1$, it follows that~$\ell=1$.  In other
  words, each element of~$\mathcal{N}(n,k)$ has period~$n+k$.  Further, by the
  proof of Theorem~\ref{thm: necklace bijection}, there is a commutative
  diagram of isomorphisms of sets:
  \begin{center}
    \begin{tikzcd} 
      {|kq|}\arrow[d,"\sigma^j"',pos=0.35]\arrow[r,"\psi"] & \mathcal{N}(n,k)\\
      {|D_j+kq|}\arrow[ru,"\psi"',pos=0.45]&
  \end{tikzcd}.
  \end{center}
\end{remark}

\begin{remark}  (Duality) Switching colors gives a bijection
  between~$\mathcal{N}(n,k)$ and~$\mathcal{N}(k,n)$.  Therefore, fixing vertices~$q$
  on~$C_n$ and~$q'$ on~$C_k$, Corollary~\ref{cor: permutation invariants} says
  that the cardinality of $|kq|$ on~$C_n$ is equal to that of ~$|nq'|$ on~$C_k$.  Further, when~$n$
  and~$k$ are relatively prime, Theorem~\ref{thm: necklace bijection} gives a
  combinatorial bijection between these complete linear systems.
\end{remark}

